<?php
declare(strict_types=1); require_once __DIR__.'/../app/bootstrap.php'; require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=trim((string)$_POST['name']);$email=trim((string)$_POST['email']);$password=(string)$_POST['password'];$role=(string)$_POST['role'];if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10||!in_array($role,['admin','seller','stock_manager'],true))throw new RuntimeException();$s=$pdo->prepare('INSERT INTO users(name,email,password,role,active,must_change_password) VALUES(?,?,?,?,1,1)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]);flash('Utilizador criado.');}catch(Throwable $e){flash('Não foi possível criar. Verifique o email e use uma palavra-passe com pelo menos 10 caracteres.','error');}redirect('users.php');}
$rows=$pdo->query('SELECT id,name,email,role,active,created_at FROM users ORDER BY id DESC')->fetchAll();layout_start('Utilizadores');echo '<section class="panel"><h2>Criar utilizador interno</h2><form method="post">'.csrf_field().'<div class="form-grid"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Palavra-passe inicial (mínimo 10 caracteres)</label><input name="password" type="password" minlength="10" required></div><div class="field"><label>Perfil</label><select name="role"><option value="seller">Vendedor</option><option value="stock_manager">Gestor de stock</option><option value="admin">Administrador</option></select></div></div><button>Criar utilizador</button></form></section><section class="panel"><h2>Contas internas</h2><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Email</th><th>Perfil</th><th>Estado</th><th>Criado</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['email']).'</td><td>'.e($r['role']).'</td><td>'.((int)$r['active']?'Ativo':'Inativo').'</td><td>'.e($r['created_at']).'</td></tr>';echo '</tbody></table></div></section>';layout_end();
